exports.ecommerceInvoicePDFTemplate = (data) => {
  let html = ''
  let grandTotal = 0
  let vatTotal = 0
  let surcharge = parseFloat(data.surcharge).toFixed(2);
  let total = parseFloat(data.total).toFixed(2);
  let shippingFee = total >= 100 ? 0 : 15
  let orderResponse = JSON.parse(data.orderResponseData)
  orderResponse.products.forEach((dt, i) => {
    if (dt?.status != 'Return Completed') {
      grandTotal += parseFloat(dt.totalPrice)
      vatTotal += parseFloat(dt.totalVat)

      // Calculate VAT percentage
      let vatPercent = (dt.totalVat / dt.totalPrice) * 100;
      // eslint-disable-next-line no-unused-vars
      vatPercent = Math.round(vatPercent)
      // VAT amount for each product
      let vatAmount = dt.totalVat;
      vatAmount = vatAmount.toFixed(2);

      let priceExlVat = parseFloat(dt.totalPrice) - parseFloat(dt.totalVat)
      priceExlVat = priceExlVat.toFixed(2);
      let totalPrice = dt.totalPrice.toFixed(2)
      let quantity = parseInt(dt.productQuantity)
      let productName = dt.productName
      let tableRow = `  <tr>
  <th scope="row">${i + 1}</th>
  <td>${productName}</td>
  <td>${quantity}</td>
  <td>${priceExlVat} INR</td>
  <td>${vatAmount} INR</td>
  <td>${totalPrice} INR</td>
  </tr>`
      html += tableRow
    }
  })
  let subTotal = grandTotal - vatTotal
  subTotal = subTotal.toFixed(2)

  grandTotal = grandTotal.toFixed(2)
  vatTotal = vatTotal.toFixed(2)

  const date = new Date(data.orderDate);
  const formattedDate = `${date.getDate()}/${date.getMonth() + 1}/${date.getFullYear()}`;
  return `
   <!DOCTYPE htmlPUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd"><html lang="en" xmlns="http://www.w3.org/1999/xhtml" xmlns:o="urn:schemas-microsoft-com:office:office"style="width:100%;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;padding:0;Margin:0"><head><meta charset="UTF-8"><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Invoice</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.0.2/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://fonts.googleapis.com/css?family=Roboto:300,400,500,700&display=swap" rel="stylesheet" /><style type="text/css"> body { font-family: 'Roboto', sans-serif; } hr { /* margin: 1.875em 0; */ border: none; border-bottom: solid 1px #000000; } .dashed-2 { border: none; height: 1px; background: #000; background: repeating-linear-gradient(90deg, #000, #000 3px, transparent 3px, transparent 6px); } .line { width: 40%; text-align: center; border-bottom: 2px dotted rgb(165, 165, 165); line-height: 0.1em; margin: auto } </style></head><body><div class="container mt-4 "><div class="card "> <div class="card-body"> <div class="col-12"> <img src="https://peko.one/wp-content/uploads/2022/03/Untitled-design3.png" alt="" style="width: 200px;"> <div class="col-12 mt-5 "> <div class="col-3"> <p class="h6 mb-1">Buyer</p> <p class="mb-0">${orderResponse?.address?.address ?? 'Not Available'}</p> <p class="mb-0">${orderResponse?.address?.phoneNumber ?? 'Not Available'}</p> </div> </div> <div class="col-12 mt-2"> <p class="h6 mb-1">Invoice Date</p> <p class="mb-0">${formattedDate}</p> </div> <div class="col-12 mt-2"> <table class="table"> <thead> <tr> <th scope="col">No</th> <th scope="col">Product Name</th> <th scope="col">Qty</th> <th scope="col">Price (Excl.GST)</th> <th scope="col">GST Amount</th> <th scope="col">Total Price</th> </tr> </thead> <tbody> ${html} </tbody> </table> </div> <div class="col-12" style="display:flex; justify-content:flex-end"> <div class="p-3"> <h6>PRICE BREAKUP</h6> <table class="table table-borderless" style="width: 30%"> <tbody class="lh-lg"> <tr> <td> Subtotal: </td> <td class="ps-3"> ${subTotal} INR</td> </tr> <tr> <td> VAT: </td> <td class="ps-3"> ${vatTotal} INR</td> </tr> <tr> <td> Shipping & Handing: </td> <td class="ps-3"> ${shippingFee} INR</td> </tr> <tr> <td> Sucharge: </td> <td class="ps-3"> ${surcharge} INR</td> </tr> <tr> <td> Total: </td> <td class="ps-3"> ${total} INR</td> </tr> </tbody> </table> </div> </div> </div> </div></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.0.2/dist/js/bootstrap.bundle.min.js"></script></body></html>
    `;
};

